INSERT INTO "modules" (
  "id", "config_version_id", "stable_id", "name", "goal", "step_1", "step_2", "step_3", "checkpoint", "constraints", "active"
) VALUES
  ('0cd9435d-13d4-44a1-85a9-092a4abaf888'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M01', 'Выбор направления', 'Сформировать 2–3 реалистичные карьерные гипотезы и понять, что проверять дальше.', 'Сравнить 10–15 вакансий по 2–3 интересующим ролям.', 'Выписать повторяющиеся задачи и требования.', 'Выбрать 1 основную и 1 запасную карьерную гипотезу.', 'Есть 1–2 роли, по которым студент может объяснить: что делает специалист, что уже подходит и чего пока не хватает.', 'Если Q4_A1 выбран: не «выбрать с нуля», а проверить выбранную роль на реальных вакансиях.', TRUE),
  ('c120fd77-8e3a-4fe2-8389-e70b5b299b5e'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M02', 'Поиск возможностей', 'Сделать поиск системным: где искать, что считать подходящей возможностью и как не терять вакансии.', 'Задать фильтры: роль, уровень, формат, локация.', 'Собрать список целевых компаний и каналов поиска.', 'Вести простой трекер откликов и раз в неделю смотреть конверсию.', 'Есть понятный список каналов, 15–20 целевых компаний/вакансий и ритм поиска.', 'Если Q4_A5 выбран: не собирать список заново, а проверить его качество и расширить каналы.', TRUE),
  ('c46d9f3e-b112-4c1a-82ef-3680db034884'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M03', 'Первый опыт', 'Получить или лучше упаковать опыт, который можно показать работодателю.', 'Перевести учебные и проектные задачи в формат опыта: задача → действие → результат.', 'Найти практику, стажировку, проект или роль в сообществе, где появится реальный результат.', 'Собрать 1–3 доказательства: кейс, репозиторий, презентация, метрика, отзыв.', 'В резюме и на собеседовании есть минимум один конкретный кейс, а не только список дисциплин.', 'Если Q4_A3/Q4_A4 выбран: акцент на упаковку существующего опыта и на более сильный следующий кейс.', TRUE),
  ('49099f86-cde7-41f4-8337-9814c96e8171'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M04', 'Навыки и требования рынка', 'Понять разрыв между текущим профилем и требованиями к выбранной роли.', 'Разобрать 15–20 вакансий и выписать повторяющиеся навыки.', 'Разделить требования на must-have и nice-to-have.', 'Выбрать 1–2 навыка, которые можно усилить и подтвердить за ближайший месяц.', 'Есть короткая карта навыков: уже есть / нужно подтянуть / чем подтвердить.', 'Не превращать результат в длинный список курсов: в траектории должно быть не больше 2 приоритетных навыков.', TRUE),
  ('29c914e6-d8e3-4e54-ae5d-cac848b5113a'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M05', 'Резюме и отклик', 'Повысить шанс дойти от отклика до разговора с работодателем.', 'Сделать резюме под целевую роль: релевантный опыт выше, лишнее убрать.', 'Описать проекты через конкретные действия и результат.', 'Адаптировать резюме и короткий отклик под вакансию; использовать понятные формулировки и термины из описания роли.', 'Есть одно базовое резюме и понятный способ быстро адаптировать его под конкретную вакансию.', 'Для Q2_A8 добавить вариант «первичный фильтр»: проверить читаемость, релевантность, ключевые требования и конверсию откликов. Не обещать «обход ATS».', TRUE),
  ('b7b07de7-e0cc-43a7-9443-dcdc438926a0'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M06', 'Собеседование', 'Подготовить понятный рассказ о себе и доказательства компетенций.', 'Собрать самопрезентацию на 60–90 секунд.', 'Подготовить 6–8 историй по схеме ситуация → действие → результат.', 'Провести минимум одно тренировочное собеседование и разобрать слабые ответы.', 'Студент может уверенно объяснить свой опыт, мотивацию и привести примеры по ключевым компетенциям.', 'Подстраивать примеры под выбранную роль; не выдавать универсальный список «правильных ответов».', TRUE),
  ('cb541dc5-5aa1-4839-987f-2649721c8335'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M07', 'Тестовые задания', 'Сделать выполнение тестовых более предсказуемым и понятным работодателю.', 'До начала зафиксировать требования, ограничения и критерии готовности.', 'Структурировать решение: логика, допущения, результат, краткое пояснение.', 'После выполнения сохранять сильные решения как кейсы и разбирать обратную связь.', 'Есть повторяемый шаблон выполнения тестового и 1–2 сохранённых примера.', 'Для технических направлений можно подставлять факультетские/клубные практики; конкретику подключать позже из каталога.', TRUE),
  ('a7372a1b-aa2c-4a10-a0e8-59b954b67873'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M08', 'Устойчивый поиск', 'Выстроить ритм поиска, который можно совмещать с учёбой и не оценивать себя по каждому отказу.', 'Выделить 2–3 фиксированных окна в неделю на поиск и отклики.', 'Считать воронку: отклики → ответы → интервью → следующие этапы.', 'Если конверсия низкая, менять один элемент за раз: вакансии, резюме, канал или подготовку.', 'Есть недельный ритм и цифры воронки, по которым понятно, что именно нужно улучшать.', 'Фокус на управляемых действиях и воронке. Не давать психологических диагнозов или обещаний.', TRUE),
  ('a07f8db3-8f3a-4471-99e3-444514598ebc'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M09', 'Выбор стажировки или оффера', 'Сравнить варианты не только по названию компании или зарплате, а по содержанию и перспективе.', 'Определить 3 обязательных критерия и 3 допустимых компромисса.', 'Сравнить задачи, команду, наставника, формат, развитие и условия.', 'До решения задать работодателю вопросы по реальной работе и ожиданиям первых месяцев.', 'Есть простая матрица сравнения и аргументированный выбор.', 'Если вариантов пока нет, модуль не должен попадать в топ только из-за общего интереса к стажировкам.', TRUE),
  ('eca9a37e-c5a4-4d11-8eb3-d303d8e30ea5'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M10', 'Развитие во время учёбы', 'Связать учёбу, проекты и работу в одну траекторию на ближайший семестр.', 'Выбрать карьерную цель на 6–12 месяцев.', 'Выбрать один проект/роль, где можно увеличить ответственность.', 'Раз в 2–3 месяца фиксировать новые результаты и обновлять резюме/портфолио.', 'Есть цель на семестр и один проект, который должен дать новый уровень опыта.', 'Подходит и тем, кто уже работает: акцент на качестве опыта и следующем уровне задач.', TRUE),
  ('2798ef0f-a63a-48bd-8ea4-1df819a723b3'::uuid, 'a8ad8398-48dc-41d7-9793-5e21248be966'::uuid, 'M11', 'Предпринимательство', 'Перевести интерес или идею в проверяемую гипотезу и определить следующий доказуемый шаг.', 'Сформулировать, для кого и какую проблему вы хотите решать; если идеи нет — выбрать 2–3 знакомые проблемные области.', 'Проверить гипотезу на реальных людях: короткие интервью и/или простой тест спроса без долгой разработки.', 'Зафиксировать факты и выбрать следующий эксперимент: прототип, пилот, первые продажи, изменение гипотезы или отказ от неё.', 'Есть не только идея, а сформулированная гипотеза, факты от потенциальных пользователей и понятный следующий эксперимент.', 'Не начинать с регистрации бизнеса, большого бизнес-плана или поиска инвестиций. Сначала проблема, пользователь и спрос. Для действующего проекта использовать подветку по стадии из листа 09.', TRUE);

